import { useState } from "react";
import { useResults } from "../context/ResultsContext";
import { useNavigate } from "react-router-dom";
import { analyzeResumes } from "../api";

export default function UploadResumes() {
  const { setResults } = useResults();
  const navigate = useNavigate();

  const [files, setFiles] = useState([]);
  const [links, setLinks] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e) => {
    const selected = Array.from(e.target.files);
    setFiles(selected);
    setLinks(selected.map(() => ""));
  };

  const handleLinkChange = (index, value) => {
    const updated = [...links];
    updated[index] = value;
    setLinks(updated);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    files.forEach((file) => formData.append("resumes", file));
    links.forEach((link) => formData.append("github_links", link));

    try {
      setLoading(true);

      const data = await analyzeResumes(formData);
      setResults(data.results);

      navigate("/results");
    } catch (err) {
      console.error(err);
      alert("Failed to analyze resumes");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page">
      <div className="container">
        <h2>Upload Resumes</h2>
        <p>Upload resumes with optional GitHub / portfolio links.</p>

        <div className="card">
          <form onSubmit={handleSubmit}>
            <input
              type="file"
              multiple
              accept=".pdf,.docx"
              onChange={handleFileChange}
            />

            {files.map((file, i) => (
              <div key={i} style={{ marginTop: "16px" }}>
                <label>{file.name} — GitHub / Portfolio (optional)</label>
                <input
                  type="url"
                  placeholder="https://github.com/username"
                  value={links[i]}
                  onChange={(e) => handleLinkChange(i, e.target.value)}
                />
              </div>
            ))}

            <div style={{ marginTop: "20px" }}>
              <button type="submit" disabled={loading}>
                {loading ? "Analyzing..." : "Analyze Resumes"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
